let memo = null; // { at: number, payload: object }
let histMemo = null; // { at, h: { days: { "YYYY-MM-DD": { CODE: [harga, yield, hargaJual|null] } } } }
const HIST_KEY = "hist_v1";
const HIST_DAYS = 400;
const EVENTS_KEY = "events_v1";


// Tanggal WIB (UTC+7)
const wibDate = (d = new Date()) => new Date(d.getTime() + 7 * 3600e3).toISOString().slice(0, 10);

// Selalu baca ulang dari KV (maks. tiap 5 menit) agar beberapa instance Worker tidak saling menimpa riwayat.
async function loadHist(env, fresh = false) {
  if (!env.BONDS_KV) return null;
  if (!fresh && histMemo && Date.now() - histMemo.at < 5 * 60e3) return histMemo.h;
  const h = (await env.BONDS_KV.get(HIST_KEY, "json")) || { days: {} };
  histMemo = { at: Date.now(), h };
  return h;
}

// Simpan satu titik per hari (nilai terakhir hari itu). Hanya menulis ke KV bila ada perubahan.
async function recordHistory(env, payload) {
  if (!env.BONDS_KV) return;
  const h = await loadHist(env, true);
  const day = wibDate(new Date(payload.meta.updated_at));
  const snap = {};
  payload.bonds.forEach((b) => (snap[b.code] = [b.price, b.yield, b.bid ?? null]));
  const before = JSON.stringify(h.days[day] || null);
  if (before === JSON.stringify(snap)) return;
  h.days[day] = snap;
  const keys = Object.keys(h.days).sort();
  keys.slice(0, Math.max(0, keys.length - HIST_DAYS)).forEach((k) => delete h.days[k]);
  await env.BONDS_KV.put(HIST_KEY, JSON.stringify(h));
}

const round = (n, d = 4) => Math.round(n * 10 ** d) / 10 ** d;

function issuerFrom(r) {
  if (r.bond_category === "Negara") return "Pemerintah Republik Indonesia";
  const n = String(r.bond_name || "")
    .replace(/^(Obligasi|Sukuk)(\s+(Berkelanjutan|Subordinasi|Mudharabah|Ijarah|Syariah|Wakalah))*(\s+[IVXLC]+)?\s+/i, "")
    .replace(/\s+(Tahap|Th\.?|Tahun|Seri)\b.*$/i, "")
    .trim();
  return n || r.bond_name || r.bond_code;
}

// Arah harga: purchase_rule.buy = nasabah MEMBELI ("Harga Beli" di situs),
// purchase_rule.sell = nasabah MENJUAL kembali ("Harga Jual").
function normalize(r, docBase) {
  const buy = r.purchase_rule?.buy?.tiers?.[0] ?? {};
  const sell = r.purchase_rule?.sell?.tiers?.[0] ?? {};
  const bidOk = Number(sell.price) > 0 && sell.yield_status === "ACTIVE";
  const syariah = Number(r.is_syariah) === 1;
  return {
    code: r.bond_code,
    name: r.bond_name,
    issuer: issuerFrom(r),
    type: syariah ? "Sukuk" : r.bond_category === "Negara" ? "Government" : "Corporate",
    coupon: Number(r.coupon_rate),
    yield: round(Number(buy.yield) || Number(r.ytm) || 0, 3),
    price: round(Number(buy.price) || Number(r.sell_percent) || 0, 4),
    bid: bidOk ? round(Number(sell.price), 4) : null,
    bidYield: bidOk ? round(Number(sell.yield), 3) : null,
    rating: r.rating || "",
    maturity: r.maturity_date,
    frequency: Number(r.coupon_payment) || 2,
    currency: "IDR",
    min: Number(r.purchase_rule?.buy?.min_nominal) || 10000000,
    multiple: Number(r.purchase_rule?.buy?.multiple_nominal) || 5000000,
    dayCount: r.day_count_basis || "ACTUAL/ACTUAL",
    issueDate: r.issue_date || null,
    couponType: r.coupon_type === "Fixed" ? "Tetap (fixed)" : r.coupon_type || null,
    lastCoupon: r.last_coupon_date || null,
    nextCoupon: r.next_coupon_date || null,
    settlement: r.settlement_date || null,
    syariah,
    best: Number(r.best_bond) === 1,
    doc: r.file && docBase ? docBase + r.file : null,
  };
}

async function fetchSource(env) {
  const { api, page, docBase } = SRC(env);
  if (!api) throw new Error("Sumber data obligasi belum diatur di profil (sources.bondApi).");
  let origin = "";
  try { origin = new URL(page || api).origin; } catch (e) {}
  const label = (page || api).replace(/^https?:\/\//, "").replace(/\/+$/, ""); // mis. "contoh.co.id/produk/bonds"
  const host = label.split("/")[0];
  const res = await fetch(api, {
    headers: {
      "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/130 Safari/537.36",
      Accept: "application/json, text/plain, */*",
      ...(page ? { Referer: page } : {}),
      ...(origin ? { Origin: origin } : {}),
    },
    signal: AbortSignal.timeout(15000),
  });
  const text = await res.text();
  if (!res.ok) throw new Error(`${host} menjawab HTTP ${res.status}`);
  let json;
  try { json = JSON.parse(text); } catch { throw new Error(`Respons ${host} bukan JSON (kemungkinan diblokir).`); }
  if (!Array.isArray(json?.data)) throw new Error(`Format API ${host} berubah.`);
  const bonds = json.data
    .filter((r) => r?.bond_code && (r.status ?? "ACTIVE") === "ACTIVE" && Number(r.active ?? 1) === 1)
    .map((r) => normalize(r, docBase))
    .filter((b) => b.price > 30 && b.price < 200 && /^\d{4}-\d{2}-\d{2}$/.test(b.maturity || ""))
    .sort((a, b) => a.type.localeCompare(b.type) || a.maturity.localeCompare(b.maturity));
  if (!bonds.length) throw new Error(`Tidak ada obligasi aktif di respons ${host}.`);
  return {
    meta: { updated_at: new Date().toISOString(), source: label, count: bonds.length },
    bonds,
  };
}

// Batas tulis KV paket gratis 1.000/hari per akun: cadangan "last_good" hanya ditulis ulang bila isi obligasinya berubah
// (riwayat sudah hanya menulis bila titik hari ini berubah). Penyimpanan berjalan di ctx.waitUntil agar respons tidak menunggu.
let savedSig = null;
async function saveKv(env, payload) {
  const sig = JSON.stringify(payload.bonds);
  if (savedSig === null) savedSig = JSON.stringify(((await env.BONDS_KV.get("last_good", "json")) || {}).bonds || null);
  if (sig !== savedSig) { await env.BONDS_KV.put("last_good", JSON.stringify(payload)); savedSig = sig; }
  await recordHistory(env, payload).catch((e) => console.error("riwayat:", e.message));
}

async function getBonds(env, force = false, ctx = null) {
  if (!force && memo && Date.now() - memo.at < TTL_MS) return { payload: memo.payload, state: "memory" };
  try {
    const payload = await fetchSource(env);
    memo = { at: Date.now(), payload };
    if (env.BONDS_KV) {
      const save = saveKv(env, payload).catch((e) => console.error("KV:", e.message));
      if (ctx) ctx.waitUntil(save); else await save;
    }
    return { payload, state: "live" };
  } catch (e) {
    if (memo) return { payload: memo.payload, state: "stale-memory", error: e.message };
    if (env.BONDS_KV) {
      const saved = await env.BONDS_KV.get("last_good", "json");
      if (saved) return { payload: saved, state: "stale-kv", error: e.message };
    }
    throw e;
  }
}

const json = (obj, status = 200, extra = {}) =>
  new Response(JSON.stringify(obj), {
    status,
    headers: { "content-type": "application/json; charset=utf-8", "cache-control": "no-store", ...extra },
  });

// HTML + judul berawalan brand + window.PROFILE (profil untuk kode klien)
const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c]);
const html = (env, extra = "") => HTML.replace("<title>Bond Insight</title>", `<title>${esc(title(env, "Bond Insight"))}</title>${profileScript(env)}${themeHead(BOND_THEME_CSS)}${extra}`);

const page = (env) =>
  new Response(html(env), {
    headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-cache", "x-robots-tag": "noindex" },
  });

const cleanEvent = (e) => ({
  id: String(e.id || crypto.randomUUID()).slice(0, 40),
  title: String(e.title || "").slice(0, 80),
  start: /^\d{4}-\d{2}-\d{2}$/.test(e.start) ? e.start : null,
  end: /^\d{4}-\d{2}-\d{2}$/.test(e.end || "") ? e.end : null,
  note: String(e.note || "").slice(0, 200),
  kind: ["offer", "note"].includes(e.kind) ? e.kind : "note",
});

// ---------- PDF detail produk ----------
// File PDF dibuat terjadwal oleh GitHub Actions (rilis "pdf" di repo proyek ini: GITHUB_REPO, atau PDF_REPO bila diisi) dan diteruskan
// dari sini, supaya link di email tetap beralamat workers.dev.
// Kalau PDF-nya belum ada (produk baru, jadwal belum jalan), nasabah dialihkan ke halaman produknya.
async function pdfFile(env, name, fallback) {
  const repo = env.PDF_REPO || env.GITHUB_REPO;
  const r = repo ? await fetch(`https://github.com/${repo}/releases/download/pdf/${name}`, { cf: { cacheTtl: 1800, cacheEverything: true } }).catch(() => null) : null;
  if (!r || !r.ok) return Response.redirect(fallback, 302);
  return new Response(r.body, { headers: { "content-type": "application/pdf", "content-disposition": `inline; filename="${name}"`, "cache-control": "public, max-age=1800", "x-robots-tag": "noindex" } });
}

/** Ringkasan "Hari ini" di Tool Hub: yield SBN tenor utama (PHEI IGSYC) + yield korporasi 2 tahun per rating. */
export async function hubToday(env, ctx) {
  const c = await getCurve(env, false, ctx);
  return { date: c.date, state: c.state, error: c.error || null, at: c.fetched_at, source: c.source, rates: keyRates(c, [1, 2, 5, 10]),
    corp2: Object.fromEntries(["AAA", "AA", "A"].map((k) => [k, interp(corpCurve(c, k), 2)]).filter((x) => x[1] != null)) };
}
export default withCron({
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    if (url.pathname === HUB_FEED) {
      if (!hubFeedAllowed(request, env)) return new Response("forbidden", { status: 403 });
      try { return json(await hubToday(env, ctx)); } catch (e) { return json({ error: e.message }, 502); }
    }
    if (url.pathname === "/app") {
      const p = profile(env), a = p.app, ua = request.headers.get("user-agent") || "";
      const to = (/android/i.test(ua) && (a.android || a.download)) || (/iphone|ipad|ipod|macintosh/i.test(ua) && (a.ios || a.download)) || p.contact.website || a.download;
      return to ? Response.redirect(to, 302) : new Response("Tautan aplikasi belum diatur di profil.", { status: 404, headers: { "content-type": "text/plain; charset=utf-8" } });
    }
    // ---- Yang tetap terbuka untuk nasabah: /app (di atas), tampilan /share, dan data yang dipakainya (obligasi & riwayat, hanya GET).
    // ---- Aplikasi internal ("/") dan momen konten (/data/events.json) hanya untuk yang login lewat Tool Hub dan punya akses Bond Insight.
    const isApp = url.pathname === "/" || url.pathname === "/index.html", isEvents = url.pathname === "/data/events.json";
    let me = null;
    if (isApp || isEvents) {
      if (!HUBSSO.ready(env)) return HUBSSO.notReady();
      const tk = await HUBSSO.ticket(request, env); if (tk) return tk;
      me = await HUBSSO.user(request, env);
      if (!me) return isApp ? HUBSSO.login(request, env) : json({ error: "Belum login atau sesi habis. Muat ulang halaman dari Tool Hub." }, 401);
      if (request.method !== "GET" && !HUBSSO.sameOrigin(request)) return json({ error: "Permintaan ditolak." }, 403);
    }
    if (url.pathname === "/logout") return HUBSSO.logout(env);
    if (url.pathname === "/data/history.json") {
      const h = await loadHist(env).catch(() => null);
      return json(h ? { kv: true, days: h.days } : { kv: false, days: {} }, 200, { "cache-control": "public, max-age=300" });
    }
    if (url.pathname === "/data/events.json") {
      if (request.method === "GET") {
        const list = env.BONDS_KV ? (await env.BONDS_KV.get(EVENTS_KEY, "json")) || [] : [];
        return json({ kv: !!env.BONDS_KV, editable: !!(env.BONDS_KV && env.EDIT_KEY), events: list });
      }
      if (request.method === "POST") {
        if (!env.BONDS_KV || !env.EDIT_KEY) return json({ error: "Penyimpanan bersama belum diaktifkan (perlu KV BONDS_KV dan secret EDIT_KEY)." }, 400);
        if (request.headers.get("x-edit-key") !== env.EDIT_KEY) return json({ error: "Kode edit salah." }, 403);
        let body;
        try { body = await request.json(); } catch { return json({ error: "Format salah." }, 400); }
        const list = (Array.isArray(body?.events) ? body.events : []).map(cleanEvent).filter((e) => e.title && e.start).slice(0, 200);
        await env.BONDS_KV.put(EVENTS_KEY, JSON.stringify(list));
        return json({ ok: true, events: list });
      }
      return json({ error: "Metode tidak didukung." }, 405);
    }
    const bm = /^\/pdf\/([A-Za-z0-9_-]{2,40})$/.exec(url.pathname);
    if (bm) return pdfFile(env, `bond-${bm[1]}.pdf`, `${url.origin}/share?bond=${bm[1]}`);
    // Kurva yield PHEI (data publik, ikut dibaca tampilan /share)
    if (url.pathname === "/data/curve.json") {
      try { return json(await getCurve(env, false, ctx), 200, { "cache-control": "public, max-age=600" }); }
      catch (e) { return json({ error: e.message }, 502); }
    }
    if (url.pathname === "/data/curve-history.json") return json(await curveHistory(env).catch(() => ({ kv: false, days: {} })), 200, { "cache-control": "public, max-age=600" });
    if (url.pathname === "/data/news.json") return json(await newsFor(BOND_NEWS_RE, 12, BOND_TOP_RE), 200, { "cache-control": "public, max-age=1800" });
    if (url.pathname === "/data/bonds.json") {
      try {
        const r = await getBonds(env, url.searchParams.has("refresh"), ctx);
        return json({ ...r.payload, meta: { ...r.payload.meta, state: r.state, error: r.error } }, 200, { "x-bonds-state": r.state, "access-control-allow-origin": "*" });   // "*": data ini memang terbuka; dibaca Email Studio untuk daftar pilihan obligasi
      } catch (e) {
        return json({ error: e.message }, 502);
      }
    }
    if (url.pathname === "/share") return page(env);
    if (isApp) {
      // hanya dipakai di dalam dashboard Tool Hub: dibuka langsung -> pindah ke tab-nya di hub
      // admin Tool Hub: menu Generator Konten, Kalender Konten, Buat Konten IG (lainnya disembunyikan di halaman)
      return new Response(html(env, `<script>${HUBSSO.onlyInHub(env)}window.ME={admin:${!!(me && me.adm)}};</script>`), { headers: { "content-type": "text/html; charset=utf-8", "cache-control": "private, no-store", "content-security-policy": HUBSSO.frame(env) } });
    }
    return new Response("Tidak ditemukan", { status: 404 });
  },

  // Dipanggil apps/cron (POST /__cron, lihat shared/cron.js) Senin–Jumat 17.00 & 19.00 WIB: kurva PHEI hari itu masuk riwayat
  // walau halaman tidak dibuka, sekalian data obligasi & riwayat hariannya.
  async scheduled(_event, env) {
    const r = await Promise.allSettled([getCurve(env, true), getBonds(env, true)]);
    const err = r.filter((x) => x.status === "rejected").map((x) => x.reason.message);
    if (err.length) throw new Error(err.join("; "));
  },
});